  function cnt(m){return keys(m).length;}
  var NAMES=["Ciara","Liam","Aoife","Jack","Zara","Oisín","Emma","Tomás"];
  var INK="#1B2430",YEL="#F6CF5A";
  var V1=["x","x","x","a","n","y","t","p"];

  /* ---------- area-model picture: rows × columns, each cell = row term × column term ---------- */
  function areaSVG(rows,cols,show){ // rows/cols: [[coef,key],…]; show: function(i,j) → "text" | "?" | ""
    var cw=86,rh=58,L=64,Tp=34,W=L+cw*cols.length+6,H=Tp+rh*rows.length+6,o="";
    function txt(x,y,s,cls,extra,fill,size){return '<text class="'+cls+'" '+(extra||"")+' x="'+x+'" y="'+y+'" font-size="'+(size||17)+'" font-weight="700" text-anchor="middle" fill="'+(fill||INK)+'" font-family="Inter,sans-serif">'+s+'</text>';}
    cols.forEach(function(c,j){o+=txt(L+cw*j+cw/2,Tp-11,tm(c[0],c[1],true),"ch",'data-t="'+tm(c[0],c[1],true)+'"');});
    rows.forEach(function(r,i){o+=txt(L-12,Tp+rh*i+rh/2+6,tm(r[0],r[1],true),"rh",'data-t="'+tm(r[0],r[1],true)+'"',INK).replace('text-anchor="middle"','text-anchor="end"');
      cols.forEach(function(c,j){var s=show(i,j),q=s==="?";
        o+='<rect x="'+(L+cw*j)+'" y="'+(Tp+rh*i)+'" width="'+cw+'" height="'+rh+'" fill="'+(q?YEL:(i+j)%2?"#E9F5EE":"#fff")+'" stroke="'+INK+'" stroke-width="2"/>';
        if(s)o+=txt(L+cw*j+cw/2,Tp+rh*i+rh/2+6,s,"cell",'data-i="'+i+'" data-j="'+j+'"',INK,q?22:16);});});
    return '<svg viewBox="0 0 '+W+' '+H+'" width="100%" style="max-width:'+Math.min(340,Math.round(W*1.4))+'px" role="img" aria-label="Area model: rows '+rows.map(function(r){return tm(r[0],r[1],true);}).join(", ")+'; columns '+cols.map(function(c){return tm(c[0],c[1],true);}).join(", ")+'">'+o+'</svg>';}
