    var html=areaSVG(rows,cols,function(i,j){if(i===hi&&j===hj)return "?";var c=mul(T1(rows[i][0],rows[i][1]),T1(cols[j][0],cols[j][1]));return fmtStd(c);});
    var slips=[];var s1={};s1[k]=-cell[k];slips.push(s1);var s2={};s2[k]=rows[hi][0]+cols[hj][0];slips.push(s2);
    var s3={};s3[k===""?"x":k==="x"?(rows[hi][1]===""&&cols[hj][1]===""?"x":"x²"):"x"]=cell[k];slips.push(s3);
