    for(var t=L;t<=R;t++)o+='<line x1="'+X(t)+'" y1="'+(y-6)+'" x2="'+X(t)+'" y2="'+(y+6)+'" stroke="'+INK+'" stroke-width="1.5"/><text class="tk" data-v="'+t+'" x="'+X(t)+'" y="'+(y+26)+'" text-anchor="middle" font-size="14" font-weight="600" fill="'+INK+'" font-family="Inter,sans-serif">'+num(t)+'</text>';
