    stairs:{k:1,why:function(){return "Stage n = 1 + 2 + … + n tiles. Jumps 2, 3, 4 … so add one more each time.";},cells:function(n){var o=[];for(var i=0;i<n;i++)for(var j=0;j<=i;j++)o.push([i,j,"y"]);return o;}},
    lin:{k:0,why:function(p){return "Each stage adds "+p.r+" tiles (same jump): linear.";},cells:function(n,p){var o=[],i,j;for(j=0;j<p.e;j++)o.push([0,j,"y"]);for(i=0;i<n;i++)for(j=0;j<p.r;j++)o.push([i+1,j,"g"]);return o;}},
    dbl:{k:2,why:function(p){return "× "+p.r+" every stage: exponential.";},cells:function(n,p){var N=p.c*Math.pow(p.r,n-1),cols=Math.ceil(Math.sqrt(N)),o=[];for(var i=0;i<N;i++)o.push([i%cols,Math.floor(i/cols),"b"]);return o;}}
